.table-container {
  border-radius: 8px;
  box-shadow: 0 4px 6px rgb(0 0 0 / 10%);
  overflow: hidden;

  .table-controls {
    display: flex;
    align-items: center;
    padding: 20px;
    justify-content: center;

    .filter-field {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 10px;
      flex-direction: row;
      border: none;
      border-radius: 10px;
      background-color: var(--input-disabled-bg);
