    h2 {
      color: var(--input-disabled-bg);
      margin-bottom: 12px;
    }

    p {
      color: var(--input-disabled-bg);
    }
  }
}

@media (width <=768px) {
  .table-container {
    .table-controls {
      flex-direction: column;
      align-items: center;

      .filter-field {
        width: 80%;
        margin-right: 0;
        margin-bottom: 12px;
      }
    }
  }
}

