  animation: toast-slide-in 0.3s ease-out;
}

@keyframes toast-slide-in {
  from {
    opacity: 0;
    transform: translateX(24px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.toast-container {
  position: relative;
  display: block;
  width: 360px;
  max-width: calc(100vw - 40px);
  border-radius: 12px;
