  gap: 1.25rem;
}

.card-meta-item {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.875rem;
  color: var(--color-text-gray-400);
}

.card-meta-icon {
  width: 1rem;
  height: 1rem;
  opacity: 0.6;
}

/* ---------- SQUARE CARD SPECIFIC ---------- */
.card-square-content {
  width: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.card-square-title {
  font-size: 1rem;
  color: var(--color-text-gray-900);
  text-align: center;
}

.card-square-icon {
  width: 3rem;
  height: 3rem;
}

/* ---------- UTILITY HELPERS ---------- */
.truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.text-center {
  text-align: center;
}

/* ---------- RESPONSIVE ADJUSTMENTS ---------- */
@media (max-width: 640px) {
  .card-horizontal {
    padding: 0.75rem 1rem;
    gap: 0.75rem;
  }
  
  .card-square {
    padding: 1rem 2rem;
  }
  
  .card-square-content {
    width: 80%;
  }
  
  .card-badge-wrapper {
    gap: 1rem;
  }
  
  .card-meta-list {
    gap: 0.75rem;
  }
}

@media (max-width: 480px) {
  .card-horizontal {
    flex-wrap: wrap;
    justify-content: center;
    text-align: center;
  }
  
  .card-content {
    width: 100%;
    align-items: center;
  }
  
  .card-badge-wrapper {
    width: 100%;
    align-items: center;
  }
  
  .card-meta-list {
    justify-content: center;
  }
  
  .card-square {
    padding: 1rem;
  }
  
  .card-square-content {
    width: 100%;
  }
}

