export interface ICaoImage {
  src: string;
  alt: string;
}
export interface ICaoKPI {
  title: string;
  value: string;
  textColor: string;
  borderColor: string;
  icon: ICaoImage;
}

@Component({
  selector: "cao-kpi",
  imports: [CommonModule],
