  }
  100% {
    transform: translateX(100%) scaleX(0.2);
  }
}

@keyframes cao-progress-bar-secondary {
  0% {
    transform: translateX(-100%) scaleX(0.1);
  }
  50% {
    transform: translateX(-100%) scaleX(0.1);
  }
  80% {
    transform: translateX(40%) scaleX(0.4);
  }
  100% {
    transform: translateX(100%) scaleX(0.1);
  }
}

@keyframes cao-progress-bar-dots {
  to {
    background-position-x: -8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cao-progress-bar__fill,
  .cao-progress-bar__buffer {
    transition: none;
  }

  .cao-progress-bar__bar--primary,
  .cao-progress-bar__bar--secondary {
    animation-duration: calc(var(--_duration) * 3);
  }

  .cao-progress-bar__dots {
    animation: none;
  }
}

