  border-color: var(--success);
}

/* após perder o foco, "neutraliza" o success para transparente */
.custom-timepicker.valid:not(.mat-focused) .mat-mdc-text-field-wrapper {
  border-color: transparent;
}

.custom-timepicker .mdc-line-ripple {
  display: none;
